struct bfp16ebs8 {};
struct bfp16ebs16 {};

inline __attribute__((always_inline)) int32_t as_int32(float a) {
  return *(int32_t *)&a;
}
inline __attribute__((always_inline)) long long as_int64(double a) {
  return *(int64_t *)&a;
}
inline __attribute__((always_inline)) float as_float(int a) {
  return *(float *)&a;
}
inline __attribute__((always_inline)) double as_double(long long a) {
  return *(double *)&a;
}

